import {shouldContinueToolLoop, toRejectionError} from './orchestratorHelpers.js';
import type {ToolRegistry} from './tools/registry.js';
import type {ToolCall} from '../types/ai.js';
import {AIError} from '../types/ai.js';

// All three conditions matter; dropping the registry check spins the tool loop.

const A_TOOL: ToolCall[] = [{id: 't1', name: 'lookup', input: {}}];
const REGISTRY = {} as ToolRegistry;

describe('shouldContinueToolLoop', () => {
  it('continues when the model requested a tool and a registry can run it', () => {
    expect(shouldContinueToolLoop('tool_use', A_TOOL, REGISTRY)).toBe(true);
  });

  it('stops when no registry is configured, whatever the model asked for', () => {
    expect(shouldContinueToolLoop('tool_use', A_TOOL, undefined)).toBe(false);
  });

  it('stops when the model named no tool', () => {
    expect(shouldContinueToolLoop('tool_use', [], REGISTRY)).toBe(false);
  });

  it('stops when the model finished for a reason other than tool use', () => {
    expect(shouldContinueToolLoop('end_turn', A_TOOL, REGISTRY)).toBe(false);
  });
});

describe('toRejectionError', () => {
  // The catch hands onError this: the thrown value when it already is one, else a wrapper with the original as cause.
  it('wraps a string, object, or undefined rejection with a readable message and the original as cause, and passes an Error through unchanged', () => {
    const thrown = {code: 503, detail: 'upstream down'};
    const original = new AIError('rate limited', 'RATE_LIMITED');

    expect(toRejectionError(original)).toBe(original);

    const asString = toRejectionError('string boom');
    expect(asString.message).toBe('string boom');
    expect(asString.cause).toBe('string boom');

    const asObject = toRejectionError(thrown);
    expect(asObject.message.length).toBeGreaterThan(0);
    expect(asObject.cause).toBe(thrown);

    const asUndefined = toRejectionError(undefined);
    expect(asUndefined.message.length).toBeGreaterThan(0);
    expect(asUndefined.cause).toBe(undefined);
  });
});

